import{_ as t}from"./chunks/824e3b9231d2c7af8ce9.CvtpRolK.js";import{_ as o,o as a,c as i,a5 as n}from"./chunks/framework.DNkHA0lr.js";const y=JSON.parse('{"title":"The Micro Education Business Model (How To Monetize Your Knowledge)","description":"","frontmatter":{"title":"The Micro Education Business Model (How To Monetize Your Knowledge)","search":false,"sidebar":false},"headers":[],"relativePath":"en/letters/the-new-wave-of-micro-businesses-monetize-your-knowledge.md","filePath":"en/letters/the-new-wave-of-micro-businesses-monetize-your-knowledge.md"}'),s={name:"en/letters/the-new-wave-of-micro-businesses-monetize-your-knowledge.md"};function r(l,e,p,u,h,d){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="the-micro-education-business-model-how-to-monetize-your-knowledge" tabindex="-1">The Micro Education Business Model (How To Monetize Your Knowledge) <a class="header-anchor" href="#the-micro-education-business-model-how-to-monetize-your-knowledge" aria-label="Permalink to &quot;The Micro Education Business Model (How To Monetize Your Knowledge)&quot;">​</a></h1><p>Dan Koe · 2023-04-14 · <a href="https://thedankoe.com/letters/the-new-wave-of-micro-businesses-monetize-your-knowledge/" target="_blank" rel="noreferrer">原文</a> · <a href="/letters/the-new-wave-of-micro-businesses-monetize-your-knowledge">返回中文译文</a></p><p><a href="https://www.youtube.com/embed/XgAMayF-JZY?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>When I first started out in business I felt like freelancing was the only option.</p><p>I didn’t feel authoritative enough to build a personal brand.</p><p>I didn’t have the money to order quality products for an eCommerce brand.</p><p>I didn’t even know what consulting was.</p><p>Agency and freelance work are marketed towards beginners, and for good reason:</p><ul><li>You can learn skills for free (or cheap with courses compared to a college degree).</li><li>You don’t need to invest time in building an audience to land clients (although I highly recommend building one).</li><li>You only need 3-4 clients a month to make a great income.</li></ul><p>It was a no-brainer.</p><p>And I still think it’s a great option.</p><p>36% of the workforce are freelancers.</p><p>And with decentralization and the <a href="https://thedankoe.com/the-future-of-the-creator-economy-my-bold-prediction/" target="_blank" rel="noreferrer">future of work shifting</a>, I believe that number will skyrocket upward of 90% in the next decade. (I like making delusional predictions).</p><p>Everyone will be a freelancer.</p><p>That is, until they evolve as a creator, productize their knowledge, and scale as a one-person business. If they want to escape the feast or famine client cycle.</p><p>And still, the options are endless.</p><p>Endless niches to go into.</p><p>Endless skills to learn.</p><p>Endless outreach strategies to test.</p><p>It’s no wonder online business is so overwhelming.</p><p>It’s all so new.</p><p>It hasn’t been around for long… maybe a few decades? If that? That’s pretty insane.</p><p>And you won’t find any college course teaching the strategies that creators are.</p><p>So, for those that think freelancing is your only option, I want to present something new.</p><p>But first, I need to shed some of your limiting beliefs.</p><h2 id="education-businesses-are-the-most-meaningful-business-models-especially-for-beginners" tabindex="-1">Education Businesses Are The Most Meaningful Business Models (Especially For Beginners) <a class="header-anchor" href="#education-businesses-are-the-most-meaningful-business-models-especially-for-beginners" aria-label="Permalink to &quot;Education Businesses Are The Most Meaningful Business Models (Especially For Beginners)&quot;">​</a></h2><p>People love to talk bad about education businesses.</p><p>They think it’s just a bunch of people scamming and manipulating because information isn’t tangible.</p><p>In reality, it’s the most meaningful and results-oriented business model there is.</p><p>Especially with a broken school system.</p><p>If it weren’t for the online education industry and “scammers” selling $50 courses (I bought way too many), I would not have a 7 figure business talking about what I love. Simple as that.</p><p>You will <em>only</em> find new, specific, and relevant information inside online courses.</p><p>Who cares if you waste $50 here and there but find the one sentence that makes it all click for you.</p><p>Most are just impatient.</p><p>They’re cool with college taking 4 years to get a sub-6-figure salary and have their life taken from them, but don’t believe in a decentralized individual teaching from experience and results. It’s going to take close to the same amount of time, but you’ll see exponential results once it clicks.</p><p>Fix your expectations.</p><p>To understand the importance of information and education (especially in business) we must understand evolution.</p><p>Animals seek to replicate the information in their genes.</p><p>While humans do the same, we also have the unique trait that we seek to replicate the information in our consciousness.</p><p>We don’t only try to survive our physical form, but our mental form.</p><p>Our “mental form” is our sense of self.</p><p>We project and communicate the ideas, beliefs, and values that we identify with.</p><p>We are literally trying to reproduce who we are in every interaction.</p><p>And when people don’t agree with the beliefs we hold so tight, that is when arguments take over.</p><p>Parents instill pieces of their “self” into their children.</p><p>And the parents did the same depending on the religious ideaology, career paths, and beliefs as their parents.</p><p>In every interaction, you are spiritually impregnating the minds of others with the content of your consciousness.</p><p>Now, before I start sounding crazy, why does this matter?</p><p>Education is the pillar of progress and evolution.</p><p>Education changes human behavior.</p><p>Education creates useful people that contribute to society, earn more, and create jobs.</p><p>The education industry will only continue to grow and those that don’t accept it may be left behind.</p><p>By the way, I teach all of this in my <a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">Digital Economics masterclass</a>.</p><h2 id="education-the-creator-economy" tabindex="-1">Education &amp; The Creator Economy <a class="header-anchor" href="#education-the-creator-economy" aria-label="Permalink to &quot;Education &amp; The Creator Economy&quot;">​</a></h2><p><img src="'+t+'" alt=""></p><p>A “creator” banks on three pillars:</p><ul><li>Inspiration</li><li>Education</li><li>Entertainment</li></ul><p>Some go all in on one.</p><p>Similar to how Mr. Beast is solely an entertainment creator.</p><p>Some theme pages like “Millionaire Motivation” accounts are based on inspiration.</p><p>Many tutorial accounts are only based on education.</p><p>In my eyes, a holistic approach is best.</p><p>Like how Joe Rogan incorporates all of the above (because he leverages <em>who he is).</em></p><p>Or how I use personal experience for inspiration, philosophical musings for entertainment, and hard advice for education.</p><p>The usage of all 3 creates a sustainable business where <a href="https://thedankoe.com/the-most-profitable-niche-is-you-how-to-create-your-niche/" target="_blank" rel="noreferrer">you are the niche</a>.</p><p>The future belongs to those that hold the most mental real estate.</p><p>In other words, it belongs to those that capture attention and replicate the valuable aspects of their self.</p><p>You need to focus on having your ideas stick in the minds of your readers.</p><p>Like how when I’m in an emotional rut, I remember the big ideas from The Power Of Now by Eckhart Tolle.</p><p>I attribute my progress to him and pass along his work.</p><p>Who knows how much money he has made because of my subtle yet consistent contributions.</p><p>Stop thinking of content as a means to income.</p><p>Will your ideas be mentioned in a top 10 podcast episode?</p><p>Will your ideas be in the intro of a best selling book?</p><p>Will your ideas be mentioned in viral videos and tight knit newsletters?</p><p>Write for impact and the income will come (see: <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a>).</p><p>In order to do this, you must develop yourself.</p><p>Personal development is about solving your own problems.</p><p>Business is about solving other people’s problems.</p><p>So, develop yourself, document the solution via an education business, and develop others.</p><p>By treating <em>your life</em> as your life’s work you go on to change the course of humanity for the better.</p><p>Without realizing it, you impact individuals in a manner that induces positive behavior change.</p><p>From the individual to collective, you change the world for the better. Even if you don’t want to think of it that way.</p><h2 id="the-3-point-micro-business-model" tabindex="-1">The 3 Point Micro Business Model <a class="header-anchor" href="#the-3-point-micro-business-model" aria-label="Permalink to &quot;The 3 Point Micro Business Model&quot;">​</a></h2><p>I don’t want to overwhelm you.</p><p>I want to give you a practical business model that you can start building today.</p><p>It will be extremely difficult at the start (as ALL things are).</p><p>But as the path of mastery goes… it starts as difficult but becomes more pleasurable with time.</p><p>If you can make it past the difficulty threshold through practice, iteration, and persistence it will all work out.</p><p>Notice how I said <em>iteration</em>.</p><p>If something isn’t working, try something else.</p><p>The word “try” means that you are taking on a challenge that you have the skill to take on.</p><p>This creates the soft conditions for a flow state, or a state of maximum enjoyment.</p><p>If you’re lost, learn.</p><p>When you have direction, act.</p><p>Make mistakes. Be embarrassed. Create a giant mess so you have something to improve. And when you feel lost, repeat the process.</p><p>If I wanted to decrease my workload any further, I would still have this structure, just distributed to less social platforms.</p><p>Most of Twitter’s successful creators emulate this structure and create their own little digital reality that their followers can reside in.</p><h3 id="_1-start-a-newsletter" tabindex="-1">1) Start A Newsletter <a class="header-anchor" href="#_1-start-a-newsletter" aria-label="Permalink to &quot;1) Start A Newsletter&quot;">​</a></h3><p>Nobody wants to start a newsletter because they don’t have any subscribers.</p><p>That’s exactly why you should start one.</p><p>Nobody is watching.</p><p>Would you rather practice your writing when you don’t have subscribers? Or would you rather wait until the fear of writing a first issue to 5,000 people prevents you from writing at all?</p><p>Why should you care about writing a newsletter?</p><ul><li>It develops the most authority (short form only holds so much attention).</li><li>You own the audience you acquire (social platforms can go down at any moment).</li><li>This is where you sell your products or services to people that care about you (rather than spamming social media and looking scammy).</li></ul><p>Long form content should be the pillar of your business.</p><p>It forces you to develop depth behind your thoughts.</p><p>That way you attract a dedicated audience that actually wants to pay you (and you don’t become a shallow advice giver on other platforms).</p><p>When you have long form content, you can skip most of the sales and marketing hacks that people tell you to learn.</p><p>How do you start writing a newsletter?</p><p><strong>Hunt For High Performing Ideas</strong></p><p>It’s not animation.</p><p>It’s not captions on clips.</p><p>It’s not tweet structures.</p><p>It’s not actionable lists.</p><p>It’s not the perfect bio.</p><p>It’s not a colorful thumbnail.</p><p>It’s the ideas people collect from someone they like.</p><p>Things like animation help of course.</p><p>They catch attention and immediately boost your brands quality beyond 99% of creators.</p><p>So, if you have great ideas and want them visualized, check out <a href="https://www.keyframe.design/" target="_blank" rel="noreferrer">Keyframe</a>, my animation agency (established creators only).</p><p>To find high-performing ideas:</p><ul><li>Filter your favorite YouTubers videos by “most popular” and study the titles.</li><li>Sign up for Medium.com, select your interests, and study your homepage suggestion’s headlines daily.</li><li>Read books until a novel idea catches your attention, write it down, and use it in your writing, videos, and speaking.</li></ul><p>My absolute favorite way to generate the most ideas is by studying top tweets.</p><p>People still sleep on Twitter.</p><p>Yet, it forces people to condense what they are saying into the most impactful 280 characters (most people just drag their point on and ruin their engagement potential).</p><p>This is why my text posts on Instagram outperform most other image-based creators.</p><p>I use <a href="https://thedankoe.com/get/tweethunter" target="_blank" rel="noreferrer">TweetHunter</a> to filter the accounts I love, absorb their top ideas, and schedule my best content.</p><p><strong>Study Frameworks &amp; Use Them As Training Wheels</strong></p><p>Now that you have the idea, you need to practice articulating it in a persuasive, valuable, and impactful manner.</p><p>In other words, you need to write it in a way that illustrates the pains, problems, and solutions that people relate with and <em>want</em> to implement. I wrote about this in the <a href="https://thedankoe.com/value-creation-the-skill-that-built-my-one-person-business/" target="_blank" rel="noreferrer">Value Creation letter</a>.</p><ul><li>Study top performing tweets, deconstruct what they look like and why they work, and practice writing it with your unique idea.</li><li>Study small copywriting frameworks like PAS and AIDA to tap into human psychology.</li><li>For long form study PASTOR or the systems I give out in <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a>.</li><li>Consume social media and marketing content from the lens of a creator, not consumer, and again… practice.</li></ul><p>Ideas are only as impactful if they are consumed.</p><p>If you can’t capture and hold attention, nobody will digest what you are saying.</p><p><strong>Distribute To All Platforms</strong></p><p>Once you write a newsletter you can:</p><ul><li>Use it as a YouTube script (most people wing it and the videos fall flat).</li><li>Upload it to a blog so you can repost it for life (if it has your products or services, that’s how you sell them).</li></ul><p>Those are the only two places I upload my long form content, but you can do more like Medium if you’d like.</p><h3 id="_2-condense-into-medium-form" tabindex="-1">2) Condense Into Medium Form <a class="header-anchor" href="#_2-condense-into-medium-form" aria-label="Permalink to &quot;2) Condense Into Medium Form&quot;">​</a></h3><p>If you want to stand out on short form platforms like Twitter, Instagram, or LinkedIn you should prove your authority through medium form content.</p><p>I do this by:</p><ul><li>Taking the main ideas from my newsletter.</li><li>Outlining a shorter and more concise post.</li><li>Writing it as a Twitter thread (because you are forced to condense your ideas to be the most valuable).</li><li>Keeping the thread to 10-15 tweets in length maximum.</li><li>That way, they can be turned into an Instagram and LinkedIn carousel with a few minutes of effort.</li></ul><p>Easy.</p><p>Medium form develops more authority and generates more sales, leads, and opt ins than short form.</p><p>The longer you hold attention, the more perceived value you gain as a brand.</p><h3 id="_3-break-off-into-short-form" tabindex="-1">3) Break Off Into Short Form <a class="header-anchor" href="#_3-break-off-into-short-form" aria-label="Permalink to &quot;3) Break Off Into Short Form&quot;">​</a></h3><p>Short form is your growth and testing mechanism.</p><p>Every single part of your thread can be turned into a standalone tweet.</p><p>You can also read through your newsletter and generate ideas that way.</p><p>Or, when you are hunting for ideas, you can schedule tweets inside TweetHunter.</p><p>Why Twitter?</p><p>Because it is a testing ground.</p><p>Almost all of my newsletter ideas come from previous tweets that performed well.</p><p>That way I know that the newsletter, YouTube video, and thread will also perform well.</p><p>You’ve just created a self-sustaining content ecosystem that you can milk for your entire life.</p><h2 id="build-distribution-then-monetize" tabindex="-1">Build Distribution, Then Monetize <a class="header-anchor" href="#build-distribution-then-monetize" aria-label="Permalink to &quot;Build Distribution, Then Monetize&quot;">​</a></h2><p>Everything above will form a few levers that you must move on a daily and weekly basis.</p><p>This is how you build an audience, traffic source, or distribution.</p><p>Then, you need somewhere to send that traffic in order to monetize.</p><p>I’ve spoken about monetization methods a billion times before:</p><ul><li>Study your interests</li><li>Start a service business</li><li>Grow an audience</li><li>Work for free</li><li>Develop your process</li><li>Increase prices</li><li>Repeat 5-6</li><li>Productize your process</li><li>Scale your audience and your income scales with it</li></ul><p>But, with this 3 part micro business approach, there are a few other ways.</p><p>Shaan Puri, as an example, built his newsletter to 100k subscribers and made $50K/month from sponsorships.</p><p>If you film your newsletter as a YouTube video, you can accept sponsorships and get paid for adsense.</p><p>Maxx Chewning recently mentioned that he makes around $100K/year from adsense, but makes $1M/year from sponsorships.</p><p>Add on a digital product like Justin Welsh’s content systems and boom, you add a 3rd $100K/month income stream.</p><p>Literally the only thing you have to do is focus on building an audience (the right way), and once you do, you are set for life.</p><p>You have infinite monetization options available to you that <em>do not</em> involve monetizing from begging for donations.</p><p>Give value, build distribution, ask to get paid.</p><p>That’s it.</p><p>Enjoy your week.</p><p>– Dan Koe</p>',172)])])}const f=o(s,[["render",r]]);export{y as __pageData,f as default};
